import { queryExecutionClient } from "@dynatrace-sdk/client-query";

export default async function () {
  // --- foundation: fetch the raw records (unchanged) ---
  const data = await queryExecutionClient.queryExecute({
    body: {
      query:
        'fetch logs | filter dt.system.bucket == "audit_logs" | filter log.source != "alstom/audit/users"',
      from: "now-6h", // widen if sessions last >6h, or else you may undercount
    },
  });

  let data1 = await queryExecutionClient.queryPoll({ requestToken: data.requestToken });
  while (data1.state == "RUNNING") {
    data1 = await queryExecutionClient.queryPoll({ requestToken: data.requestToken });
  }
  const records = (data1?.result?.records ?? []) as any[];
  // ------------------------------------------------------

  // helpers
  const toMs = (t: any): number => {
    if (typeof t === "number") return t;
    if (!t) return NaN;
    // trim >ms precision to avoid parse quirks
    return Date.parse(String(t).replace(/(\.\d{3})\d+/, "$1"));
  };

  // Track last successful LOGIN per user (keyed by r.user)
  const lastLogin = new Map<string, { ts: number; origin?: string }>();

  // Track last LOGOUT per user (auto logouts carry the real user in entityId)
  // We’ll resolve a "target user" for each logout like:
  //  - if userType === 'USER_NAME', prefer r.user
  //  - else (e.g., 'SERVICE_NAME' for Session management) use r.entityId
  const lastLogout = new Map<string, number>();

  let minTs = Number.POSITIVE_INFINITY;
  let maxTs = Number.NEGATIVE_INFINITY;

  for (const r of records) {
    const ts = toMs(r.timestamp);
    if (isFinite(ts)) {
      if (ts < minTs) minTs = ts;
      if (ts > maxTs) maxTs = ts;
    }

    if (r.eventType === "LOGIN" && r.success && r.user) {
      lastLogin.set(r.user, { ts, origin: r.userOrigin });
    }

    if (r.eventType === "LOGOUT") {
      let targetUser = "";
      if (r.userType === "USER_NAME" && r.user) {
        targetUser = r.user; // manual logout (by the user)
      } else if (r.entityId) {
        targetUser = r.entityId; // auto logout (Session management)
      }
      if (targetUser) lastLogout.set(targetUser, ts);
    }
  }

  // A user is "currently logged in" if their last successful LOGIN is newer than their last LOGOUT (or no logout seen)
  const currentlyLogged = [];
  for (const [user, info] of lastLogin.entries()) {
    const lo = lastLogout.get(user);
    if (!isFinite(info.ts)) continue;
    if (lo == null || info.ts > lo) {
      currentlyLogged.push({
        user,
        lastLoginISO: new Date(info.ts).toISOString(),
        lastLoginLocal: new Date(info.ts).toLocaleString(),
        origin: info.origin || "",
      });
    }
  }

  // Sort newest first
  currentlyLogged.sort((a, b) => b.lastLoginTs - a.lastLoginTs);

  const hasTime = isFinite(minTs) && isFinite(maxTs);
  return currentlyLogged
}

