import { queryExecutionClient } from "@dynatrace-sdk/client-query";

export default async function () {
  // --- foundation (unchanged) ---
  const data = await queryExecutionClient.queryExecute({
    body: {
      query:
        'fetch logs | filter dt.system.bucket == "audit_logs" | filter log.source != "alstom/audit/users"',
      from: "now-6h",
    },
  });

  let data1 = await queryExecutionClient.queryPoll({ requestToken: data.requestToken });
  while (data1.state == "RUNNING") {
    data1 = await queryExecutionClient.queryPoll({ requestToken: data.requestToken });
  }
  const records = (data1?.result?.records ?? []) as any[];
  // --------------------------------

  const LIMIT = 10;              // top N users for the chart
  const RECENT_PER_USER = 5;     // how many recent activity rows to keep per user

  const toMs = (t: any): number => {
    if (typeof t === "number") return t;
    if (!t) return NaN;
    return Date.parse(String(t).replace(/(\.\d{3})\d+/, "$1")); // trim >ms precision
  };

  type UserAgg = {
    total: number;
    lastTs: number;
    byEventType: Record<string, number>;
    byCategory: Record<string, number>;
    recent: Array<{
      ts: number;
      tsISO: string;
      tsLocal: string;
      eventType: string;
      category: string;
      success: boolean;
      schema: string;
      scope: string;
      environmentId: string;
      userOrigin: string;
    }>;
  };

  const agg = new Map<string, UserAgg>();

  // aggregate per user
  for (const r of records) {
    const user = (r?.user || "").trim();
    if (!user) continue;

    const ts = toMs(r?.timestamp);
    const eventType = (r?.eventType || "UNKNOWN").toString();
    const category  = (r?.category || "unknown").toString();
    const success   = !!r?.success;

    const schema = r?.["dt.settings.schema_id"] || "";
    const scope  = r?.["dt.settings.scope_name"] || "";
    const environmentId = r?.environmentId || "";
    const userOrigin    = r?.userOrigin || "";

    let a = agg.get(user);
    if (!a) {
      a = {
        total: 0,
        lastTs: Number.NEGATIVE_INFINITY,
        byEventType: {},
        byCategory: {},
        recent: [],
      };
      agg.set(user, a);
    }

    // totals
    a.total += 1;
    a.byEventType[eventType] = (a.byEventType[eventType] || 0) + 1;
    a.byCategory[category]   = (a.byCategory[category]   || 0) + 1;
    if (isFinite(ts) && ts > a.lastTs) a.lastTs = ts;

    // recent activities (append then trim later)
    if (isFinite(ts)) {
      a.recent.push({
        ts,
        tsISO: new Date(ts).toISOString(),
        tsLocal: new Date(ts).toLocaleString(),
        eventType,
        category,
        success,
        schema,
        scope,
        environmentId,
        userOrigin,
      });
    }
  }

  // build sorted lists
  const usersSorted = Array.from(agg.entries()).sort((a, b) => b[1].total - a[1].total);

  // chart data (top N)
  const chart = [
    {
      name: "Events",
      data: usersSorted.slice(0, LIMIT).map(([user, a]) => ({
        name: user,
        value: a.total, // <-- total number of records/actions by this user in timeframe
      })),
    },
  ];

  // details for all users (or slice if you only want top N details)
  const details = usersSorted.map(([user, a]) => {
    // keep only the most recent N rows
    a.recent.sort((x, y) => y.ts - x.ts);
    a.recent = a.recent.slice(0, RECENT_PER_USER);

    return {
      user,
      totalEvents: a.total,
      lastActivityTs: isFinite(a.lastTs) ? a.lastTs : null,
      lastActivityISO: isFinite(a.lastTs) ? new Date(a.lastTs).toISOString() : null,
      lastActivityLocal: isFinite(a.lastTs) ? new Date(a.lastTs).toLocaleString() : null,
      byEventType: Object.keys(a.byEventType)
        .sort((x, y) => (a.byEventType[y] - a.byEventType[x]))
        .map((k) => ({ name: k, count: a.byEventType[k] })),
      byCategory: Object.keys(a.byCategory)
        .sort((x, y) => (a.byCategory[y] - a.byCategory[x]))
        .map((k) => ({ name: k, count: a.byCategory[k] })),
      recentActivities: a.recent, // small sample to show "what they did"
    };
  });

  return details;
}
